\begin{tikzpicture}
\begin{axis}[
    width=0.70\textwidth,
    height=0.45\textwidth,
    xmin=-3, xmax=3,
    ymin=-0.4, ymax=3.2,
    axis lines=middle,
    xlabel={\(t\)},
    ylabel={\(s(t)\)},
    xtick={-2,-1,0,1,2},
    ytick={1,2,3},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-3:0, samples=2] {-x};
\addplot[thick, domain=0:3, samples=2] {x};
\addplot[only marks, mark=*] coordinates {(0,0)};
\addplot[very thick, dashed, domain=-1.7:0.05, samples=2] {-x};
\addplot[very thick, dotted, domain=-0.05:1.7, samples=2] {x};
\node[fill=white, inner sep=1pt, anchor=south east] at (axis cs:-0.7,2.05) {slope \(-1\)};
\node[fill=white, inner sep=1pt, anchor=south west] at (axis cs:0.7,2.05) {slope \(1\)};
\node[fill=white, inner sep=1pt, anchor=west] at (axis cs:0.85,0.55) {instant reversal};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.72\textwidth,
    xmin=-0.42, xmax=0.42,
    ymin=-0.02, ymax=0.45,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(K(x)\)},
    xtick={-0.4,-0.2,0,0.03,0.2,0.4},
    xticklabels={\(-0.4\),\(-0.2\),\(0\),\(0.03\),\(0.2\),\(0.4\)},
    ytick={0,0.2,0.4},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-0.4:0.03, samples=2] {0.03-x};
\addplot[very thick, domain=0.03:0.4, samples=2] {x-0.03};
\addplot[only marks, mark=*] coordinates {(0.03,0)};
\draw[dashed] (axis cs:0.03,0) -- (axis cs:0.03,0.42);
\node[anchor=west] at (axis cs:0.055,0.08) {true corner};
\end{axis}
\end{tikzpicture}
